begin;

alter table public.creator_authenticity_views add column manifest_requests bigint not null default 0,add column lookup_requests bigint not null default 0,add column lookup_matched bigint not null default 0,add column lookup_unmatched bigint not null default 0,add column signed_lookup_requests bigint not null default 0,add column continuity_requests bigint not null default 0,add column event_feed_requests bigint not null default 0,add column domain_discovery_checks bigint not null default 0,add column sdk_requests bigint not null default 0,add column webhook_deliveries bigint not null default 0,add column webhook_failures bigint not null default 0;

create or replace function public.record_authenticity_view(p_slug text,p_kind text)returns void language plpgsql security definer set search_path=''as $$declare a public.creator_authenticity_profiles%rowtype;column_name text;begin column_name:=case p_kind when'page'then'page_views'when'card'then'card_views'when'badge'then'badge_views'when'qr'then'qr_resolutions'when'api'then'api_requests'when'verification_click'then'verification_clicks'when'official_account_click'then'official_account_clicks'when'domain_click'then'domain_clicks'when'emergency_replacement_click'then'emergency_replacement_clicks'when'assertion_request'then'assertion_requests'when'assertion_verification_failure'then'assertion_verification_failures'when'manifest'then'manifest_requests'when'lookup'then'lookup_requests'when'lookup_matched'then'lookup_matched'when'lookup_unmatched'then'lookup_unmatched'when'signed_lookup'then'signed_lookup_requests'when'continuity'then'continuity_requests'when'event_feed'then'event_feed_requests'when'domain_discovery'then'domain_discovery_checks'when'sdk'then'sdk_requests'when'webhook_delivery'then'webhook_deliveries'when'webhook_failure'then'webhook_failures'else null end;if column_name is null then return;end if;select*into a from public.creator_authenticity_profiles where public_slug=p_slug and display_enabled;if not found then return;end if;insert into public.creator_authenticity_views(creator_id,authenticity_profile_id,day)values(a.creator_id,a.id,current_date)on conflict do nothing;execute format('update public.creator_authenticity_views set %I=%I+1 where authenticity_profile_id=$1 and day=current_date',column_name,column_name)using a.id;end$$;
revoke all on function public.record_authenticity_view(text,text)from public;grant execute on function public.record_authenticity_view(text,text)to anon,authenticated,service_role;

alter table public.creator_identity_domains add column discovery_status text not null default'not_checked'check(discovery_status in('not_checked','verified','failed')),add column discovery_checked_at timestamptz,add column discovery_next_check_at timestamptz,add column discovery_lease_owner uuid,add column discovery_lease_expires_at timestamptz;
create or replace function public.claim_authenticity_domain_discovery(p_limit integer default 20,p_lease_owner uuid default gen_random_uuid())returns setof public.creator_identity_domains language plpgsql security definer set search_path=''as $$begin if auth.role()<>'service_role'then raise exception'service role required'using errcode='42501';end if;return query with c as(select d.id from public.creator_identity_domains d where d.verification_status='verified'and d.official and d.public_visible and(d.discovery_next_check_at is null or d.discovery_next_check_at<=now())and(d.discovery_lease_expires_at is null or d.discovery_lease_expires_at<now())order by d.discovery_checked_at nulls first for update skip locked limit greatest(1,least(p_limit,100)))update public.creator_identity_domains d set discovery_lease_owner=p_lease_owner,discovery_lease_expires_at=now()+interval'2 minutes'from c where d.id=c.id returning d.*;end$$;
revoke all on function public.claim_authenticity_domain_discovery(integer,uuid)from public,anon,authenticated;grant execute on function public.claim_authenticity_domain_discovery(integer,uuid)to service_role;

create table public.creator_authenticity_manifests(
 id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.creators(id)on delete restrict,
 authenticity_profile_id uuid not null references public.creator_authenticity_profiles(id)on delete restrict,
 manifest_version text not null check(manifest_version='audienceown-manifest-v1'),presentation_revision bigint not null,identity_revision bigint not null,
 assertion_id uuid references public.creator_authenticity_assertions(id)on delete set null,payload jsonb not null check(jsonb_typeof(payload)='object'),payload_hash text not null,
 generated_at timestamptz not null,expires_at timestamptz,superseded_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create unique index authenticity_current_manifest_idx on public.creator_authenticity_manifests(authenticity_profile_id)where superseded_at is null and revoked_at is null;

create table public.creator_continuity_statements(
 id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.creators(id)on delete restrict,
 authenticity_profile_id uuid not null references public.creator_authenticity_profiles(id)on delete restrict,
 statement_version text not null check(statement_version='audienceown-continuity-v1'),statement_type text not null check(statement_type in('account_migrated','account_replaced','handle_changed','provider_changed','emergency_replacement_activated','emergency_replacement_retired','official_domain_changed')),
 provider text not null,previous_identity_account_id uuid references public.creator_identity_accounts(id)on delete restrict,current_identity_account_id uuid references public.creator_identity_accounts(id)on delete restrict,
 previous_public_url text check(previous_public_url is null or previous_public_url~'^https://'),current_public_url text check(current_public_url is null or current_public_url~'^https://'),
 reason_code text not null check(reason_code in('authoritative_migration','verified_replacement','stable_identity_handle_change','verified_provider_change','verified_emergency_activation','emergency_resolved','verified_primary_domain_change')),
 source_identity_revision bigint not null,payload jsonb not null check(jsonb_typeof(payload)='object'),payload_hash text not null,key_id text not null,signature text not null,
 issued_at timestamptz not null,expires_at timestamptz,revoked_at timestamptz,superseded_at timestamptz,created_at timestamptz not null default now(),
 check(previous_identity_account_id is distinct from current_identity_account_id or previous_identity_account_id is null));
create unique index continuity_statement_dedupe_idx on public.creator_continuity_statements(authenticity_profile_id,statement_type,source_identity_revision,provider,coalesce(previous_public_url,''),coalesce(current_public_url,''),key_id);
create or replace function public.validate_continuity_signing_key()returns trigger language plpgsql set search_path=''as $$begin if not exists(select 1 from public.authenticity_signing_keys where key_id=new.key_id and active and revoked_at is null)then raise exception'active signing key required'using errcode='23514';end if;return new;end$$;
create trigger continuity_active_signing_key before insert on public.creator_continuity_statements for each row execute function public.validate_continuity_signing_key();
revoke all on function public.validate_continuity_signing_key()from public,anon,authenticated;

create table public.authenticity_network_subscriptions(
 id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references auth.users(id)on delete cascade,creator_id uuid not null references public.creators(id)on delete cascade,
 endpoint_url text not null check(endpoint_url~'^https://'),endpoint_host text not null,secret_ciphertext text not null,event_types text[] not null,
 challenge_hash text,challenge_expires_at timestamptz,status text not null default'pending'check(status in('pending','active','failing','disabled','revoked')),
 failure_count integer not null default 0,last_success_at timestamptz,last_failure_at timestamptz,next_attempt_at timestamptz,disabled_at timestamptz,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_user_id,endpoint_url));

create table public.authenticity_network_deliveries(
 id uuid primary key default gen_random_uuid(),subscription_id uuid not null references public.authenticity_network_subscriptions(id)on delete cascade,
 event_id text not null,event_type text not null,payload jsonb not null check(jsonb_typeof(payload)='object'),payload_hash text not null,
 attempt_count integer not null default 0,status text not null default'queued'check(status in('queued','delivering','delivered','retrying','failed','cancelled')),
 response_status integer,next_attempt_at timestamptz,lease_owner uuid,lease_expires_at timestamptz,delivered_at timestamptz,failed_at timestamptz,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(subscription_id,event_id));
create index authenticity_delivery_claim_idx on public.authenticity_network_deliveries(next_attempt_at,created_at)where status in('queued','retrying','delivering');

create trigger authenticity_subscriptions_updated before update on public.authenticity_network_subscriptions for each row execute function public.set_updated_at();
create trigger authenticity_deliveries_updated before update on public.authenticity_network_deliveries for each row execute function public.set_updated_at();
create trigger authenticity_manifests_no_delete before delete on public.creator_authenticity_manifests for each row execute function public.prevent_emergency_history_mutation();
create trigger continuity_statements_no_delete before delete on public.creator_continuity_statements for each row execute function public.prevent_emergency_history_mutation();

create or replace function public.validate_network_subscription()returns trigger language plpgsql set search_path=''as $$declare allowed constant text[]:=array['authenticity.updated','authenticity.restricted','authenticity.restored','account.official_added','account.official_removed','account.handle_changed','account.migrated','account.replaced','domain.verified','domain.revoked','emergency.activated','emergency.resolved','assertion.issued','assertion.revoked','continuity.issued'];begin if new.owner_user_id is distinct from(select owner_user_id from public.creators where id=new.creator_id)then raise exception'creator ownership required'using errcode='42501';end if;if cardinality(new.event_types)=0 or exists(select 1 from unnest(new.event_types)x where not(x=any(allowed)))then raise exception'invalid event type'using errcode='22023';end if;if lower(new.endpoint_host)<>new.endpoint_host or new.endpoint_url!~('^https://'||replace(new.endpoint_host,'.','\.')||'(?::[0-9]+)?/')then raise exception'endpoint host mismatch'using errcode='23514';end if;return new;end$$;
create trigger network_subscription_valid before insert or update on public.authenticity_network_subscriptions for each row execute function public.validate_network_subscription();
revoke all on function public.validate_network_subscription()from public,anon,authenticated;

create or replace function public.claim_authenticity_network_deliveries(p_limit integer default 20,p_lease_owner uuid default gen_random_uuid())returns setof public.authenticity_network_deliveries language plpgsql security definer set search_path=''as $$begin if auth.role()<>'service_role'then raise exception'service role required'using errcode='42501';end if;return query with c as(select d.id from public.authenticity_network_deliveries d join public.authenticity_network_subscriptions s on s.id=d.subscription_id where s.status in('active','failing')and((d.status in('queued','retrying')and(d.next_attempt_at is null or d.next_attempt_at<=now()))or(d.status='delivering'and d.lease_expires_at<now()))order by d.created_at for update of d skip locked limit greatest(1,least(p_limit,100)))update public.authenticity_network_deliveries d set status='delivering',lease_owner=p_lease_owner,lease_expires_at=now()+interval'2 minutes',attempt_count=attempt_count+1 from c where d.id=c.id returning d.*;end$$;
revoke all on function public.claim_authenticity_network_deliveries(integer,uuid)from public,anon,authenticated;grant execute on function public.claim_authenticity_network_deliveries(integer,uuid)to service_role;

create or replace function public.store_authenticity_manifest(p_profile_id uuid,p_identity_revision bigint,p_presentation_revision bigint,p_payload jsonb,p_payload_hash text,p_expires_at timestamptz default null)returns uuid language plpgsql security definer set search_path=''as $$declare a public.creator_authenticity_profiles%rowtype;p public.creator_identity_profiles%rowtype;mid uuid;aid uuid;begin if auth.role()<>'service_role'then raise exception'service role required'using errcode='42501';end if;select*into a from public.creator_authenticity_profiles where id=p_profile_id for update;select*into p from public.creator_identity_profiles where id=a.identity_profile_id;if p.identity_revision<>p_identity_revision or a.presentation_revision<>p_presentation_revision then raise exception'stale manifest revision'using errcode='40001';end if;select id into aid from public.creator_authenticity_assertions where authenticity_profile_id=a.id and revoked_at is null and superseded_at is null and expires_at>now()order by issued_at desc limit 1;select id into mid from public.creator_authenticity_manifests where authenticity_profile_id=a.id and payload_hash=p_payload_hash and revoked_at is null and superseded_at is null;if mid is not null then return mid;end if;update public.creator_authenticity_manifests set superseded_at=now()where authenticity_profile_id=a.id and revoked_at is null and superseded_at is null;insert into public.creator_authenticity_manifests(creator_id,authenticity_profile_id,manifest_version,presentation_revision,identity_revision,assertion_id,payload,payload_hash,generated_at,expires_at)values(a.creator_id,a.id,'audienceown-manifest-v1',p_presentation_revision,p_identity_revision,aid,p_payload,p_payload_hash,now(),p_expires_at)returning id into mid;insert into public.creator_authenticity_events(creator_id,identity_profile_id,authenticity_profile_id,event_type,source,metadata)values(a.creator_id,a.identity_profile_id,a.id,'manifest_generated','authenticity_network',jsonb_build_object('payloadHash',p_payload_hash));return mid;end$$;
revoke all on function public.store_authenticity_manifest(uuid,bigint,bigint,jsonb,text,timestamptz)from public,anon,authenticated;grant execute on function public.store_authenticity_manifest(uuid,bigint,bigint,jsonb,text,timestamptz)to service_role;

create or replace function public.store_continuity_statement(p_profile_id uuid,p_statement_type text,p_provider text,p_previous_account_id uuid,p_current_account_id uuid,p_previous_url text,p_current_url text,p_reason_code text,p_source_revision bigint,p_payload jsonb,p_payload_hash text,p_key_id text,p_signature text,p_issued_at timestamptz,p_expires_at timestamptz default null)returns uuid language plpgsql security definer set search_path=''as $$declare a public.creator_authenticity_profiles%rowtype;p public.creator_identity_profiles%rowtype;old_a public.creator_identity_accounts%rowtype;new_a public.creator_identity_accounts%rowtype;sid uuid;valid_rel boolean:=false;begin if auth.role()<>'service_role'then raise exception'service role required'using errcode='42501';end if;select*into a from public.creator_authenticity_profiles where id=p_profile_id for update;select*into p from public.creator_identity_profiles where id=a.identity_profile_id;if p.identity_revision<>p_source_revision then raise exception'stale identity revision'using errcode='40001';end if;if p_previous_account_id is not null then select*into old_a from public.creator_identity_accounts where id=p_previous_account_id and identity_profile_id=p.id;end if;if p_current_account_id is not null then select*into new_a from public.creator_identity_accounts where id=p_current_account_id and identity_profile_id=p.id and verification_status='verified';if not found then raise exception'verified current account required'using errcode='23514';end if;end if;if p_statement_type in('account_migrated','account_replaced','emergency_replacement_activated','emergency_replacement_retired')then select exists(select 1 from public.creator_identity_relationships r where r.identity_profile_id=p.id and r.status='active'and r.source_account_id=p_previous_account_id and r.target_account_id=p_current_account_id and r.relationship_type in('replacement_for','migrated_from','migrated_to','emergency_replacement_for'))into valid_rel;if not valid_rel then raise exception'authoritative relationship required'using errcode='23514';end if;end if;if old_a.id is not null and new_a.id=old_a.id then raise exception'self loop rejected'using errcode='23514';end if;insert into public.creator_continuity_statements(creator_id,authenticity_profile_id,statement_version,statement_type,provider,previous_identity_account_id,current_identity_account_id,previous_public_url,current_public_url,reason_code,source_identity_revision,payload,payload_hash,key_id,signature,issued_at,expires_at)values(a.creator_id,a.id,'audienceown-continuity-v1',p_statement_type,p_provider,p_previous_account_id,p_current_account_id,p_previous_url,p_current_url,p_reason_code,p_source_revision,p_payload,p_payload_hash,p_key_id,p_signature,p_issued_at,p_expires_at)on conflict(authenticity_profile_id,statement_type,source_identity_revision,provider,coalesce(previous_public_url,''),coalesce(current_public_url,''),key_id)do update set payload=excluded.payload returning id into sid;insert into public.creator_authenticity_events(creator_id,identity_profile_id,authenticity_profile_id,event_type,source,metadata)values(a.creator_id,a.identity_profile_id,a.id,'continuity_statement_issued','authenticity_network',jsonb_build_object('statementId',sid,'statementType',p_statement_type));return sid;end$$;
revoke all on function public.store_continuity_statement(uuid,text,text,uuid,uuid,text,text,text,bigint,jsonb,text,text,text,timestamptz,timestamptz)from public,anon,authenticated;grant execute on function public.store_continuity_statement(uuid,text,text,uuid,uuid,text,text,text,bigint,jsonb,text,text,text,timestamptz,timestamptz)to service_role;

alter table public.creator_authenticity_manifests enable row level security;alter table public.creator_authenticity_manifests force row level security;
alter table public.creator_continuity_statements enable row level security;alter table public.creator_continuity_statements force row level security;
alter table public.authenticity_network_subscriptions enable row level security;alter table public.authenticity_network_subscriptions force row level security;
alter table public.authenticity_network_deliveries enable row level security;alter table public.authenticity_network_deliveries force row level security;
create policy"creator manifest reads"on public.creator_authenticity_manifests for select to authenticated using(public.has_creator_permission(creator_id,'emergency_manage'));
create policy"creator continuity reads"on public.creator_continuity_statements for select to authenticated using(public.has_creator_permission(creator_id,'emergency_manage'));
create policy"developer subscription reads"on public.authenticity_network_subscriptions for select to authenticated using(owner_user_id=auth.uid());
create policy"developer subscription inserts"on public.authenticity_network_subscriptions for insert to authenticated with check(owner_user_id=auth.uid()and public.has_creator_permission(creator_id,'emergency_manage'));
create policy"developer subscription updates"on public.authenticity_network_subscriptions for update to authenticated using(owner_user_id=auth.uid())with check(owner_user_id=auth.uid());
create policy"developer subscription deletes"on public.authenticity_network_subscriptions for delete to authenticated using(owner_user_id=auth.uid());
create policy"developer delivery reads"on public.authenticity_network_deliveries for select to authenticated using(exists(select 1 from public.authenticity_network_subscriptions s where s.id=subscription_id and s.owner_user_id=auth.uid()));
revoke all on public.creator_authenticity_manifests,public.creator_continuity_statements,public.authenticity_network_subscriptions,public.authenticity_network_deliveries from public,anon,authenticated;
grant select on public.creator_authenticity_manifests,public.creator_continuity_statements to authenticated;
grant select(id,owner_user_id,creator_id,endpoint_url,endpoint_host,event_types,status,failure_count,last_success_at,last_failure_at,next_attempt_at,disabled_at,created_at,updated_at)on public.authenticity_network_subscriptions to authenticated;
grant insert(owner_user_id,creator_id,endpoint_url,endpoint_host,secret_ciphertext,event_types,challenge_hash,challenge_expires_at,status)on public.authenticity_network_subscriptions to authenticated;
grant update(endpoint_url,endpoint_host,event_types,status,disabled_at,updated_at)on public.authenticity_network_subscriptions to authenticated;grant delete on public.authenticity_network_subscriptions to authenticated;
grant select(id,subscription_id,event_id,event_type,attempt_count,status,response_status,next_attempt_at,delivered_at,failed_at,created_at,updated_at)on public.authenticity_network_deliveries to authenticated;
grant select,insert,update,delete on public.creator_authenticity_manifests,public.creator_continuity_statements,public.authenticity_network_subscriptions,public.authenticity_network_deliveries to service_role;
commit;
